-- 创建简单存储过程
DELIMITER //
CREATE PROCEDURE get_user_orders(IN user_id_param INT)
BEGIN
    SELECT * FROM orders WHERE user_id = user_id_param;
END //
DELIMITER ;

-- 调用存储过程
CALL get_user_orders(1);

-- 带输出参数的存储过程
DELIMITER //
CREATE PROCEDURE calculate_user_total(
    IN user_id_param INT,
    OUT total_amount DECIMAL(10,2),
    OUT order_count INT
)
BEGIN
    SELECT
        COALESCE(SUM(amount), 0),
        COUNT(*)
    INTO total_amount, order_count
    FROM orders
    WHERE user_id = user_id_param;
END //
DELIMITER ;

-- 调用带输出参数的存储过程
CALL calculate_user_total(1, @total, @count);
SELECT @total, @count;

-- 删除存储过程
DROP PROCEDURE IF EXISTS get_user_orders;
